{"content":"const fs = require('fs');

function main() {
  const filePath = process.argv[2];
  if (!filePath) {
    console.error('Usage: node extract.js <binary>');
    process.exit(1);
  }
  const buf = fs.readFileSync(filePath);
  if (buf.length < 64 || buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46) {
    throw new Error('Not an ELF file');
  }
  const eiClass = buf[4]; // 1 = 32-bit, 2 = 64-bit
  const eiData = buf[5];  // 1 = LE, 2 = BE
  const le = eiData === 1;
  const read16 = (off) => le ? buf.readUInt16LE(off) : buf.readUInt16BE(off);
  const read32 = (off) => le ? buf.readUInt32LE(off) : buf.readUInt32BE(off);
  const read64 = (off) => {
    const v = le ? buf.readBigUInt64LE(off) : buf.readBigUInt64BE(off);
    return v;
  };

  let phoff, phentsize, phnum;
  if (eiClass === 2) {
    // 64-bit: e_phoff at 32 (8 bytes), e_phentsize at 54 (2), e_phnum at 56 (2)
    phoff = Number(read64(32));
    phentsize = read16(54);
    phnum = read16(56);
  } else if (eiClass === 1) {
    // 32-bit: e_phoff at 28 (4 bytes), e_phentsize at 42 (2), e_phnum at 44 (2)
    phoff = read32(28);
    phentsize = read16(42);
    phnum = read16(44);
  } else {
    throw new Error('Unknown ELF class');
  }

  const out = {};

  for (let i = 0; i < phnum; i++) {
    const h = phoff + i * phentsize;
    if (h + phentsize > buf.length) break;
    let pType, pOffset, pVaddr, pFilesz;
    if (eiClass === 2) {
      // p_type(4) p_flags(4) p_offset(8) p_vaddr(8) p_paddr(8) p_filesz(8) p_memsz(8) p_align(8)
      pType = read32(h);
      pOffset = Number(read64(h + 8));
      pVaddr = read64(h + 16);
      pFilesz = Number(read64(h + 32));
    } else {
      // 32-bit: p_type(4) p_offset(4) p_vaddr(4) p_paddr(4) p_filesz(4) p_memsz(4) p_flags(4) p_align(4)
      pType = read32(h);
      pOffset = read32(h + 4);
      pVaddr = BigInt(read32(h + 8));
      pFilesz = read32(h + 16);
    }
    if (pType !== 1) continue; // PT_LOAD only
    if (pFilesz <= 0) continue;
    for (let k = 0; k + 4 <= pFilesz; k += 4) {
      const foff = pOffset + k;
      if (foff + 4 > buf.length) break;
      const val = le ? buf.readUInt32LE(foff) : buf.readUInt32BE(foff);
      const addr = pVaddr + BigInt(k);
      out[addr.toString()] = val;
    }
  }

  process.stdout.write(JSON.stringify(out));
}

main();
